<?php
declare(strict_types=1);
require __DIR__ . '/../app/bootstrap.php';
$admin=require_admin();$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
 if($action==='approve_user'||$action==='reject_user'){$status=$action==='approve_user'?'approved':'rejected';$s=$pdo->prepare("UPDATE users SET account_status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND role<>'system_admin'");$s->execute([$status,$admin['id'],$id]);$message='Account review updated.';}
 if($action==='publish'||$action==='reject_content'){$status=$action==='publish'?'published':'rejected';$s=$pdo->prepare("UPDATE content SET status=?,published_at=IF(?='published',NOW(),published_at) WHERE id=?");$s->execute([$status,$status,$id]);$message='Content moderation updated.';}
}
$pendingUsers=$pdo->query("SELECT id,full_name,email,credential_notes,created_at FROM users WHERE account_status='pending' AND role<>'system_admin' ORDER BY created_at")->fetchAll();
$pendingContent=$pdo->query("SELECT c.id,c.title,c.content_type,c.created_at,u.full_name,cat.name category_name FROM content c JOIN users u ON u.id=c.owner_id JOIN categories cat ON cat.id=c.category_id WHERE c.status='pending_review' ORDER BY c.created_at")->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>System Administrator</title><link rel="stylesheet" href="assets/css/site.css"></head><body><header><div class="wrap nav"><a class="brand" href="../index.php">Z.C. commonplace<span>.</span></a><nav class="navlinks"><a href="../index.php">Public website</a><a class="btn light" href="logout.php">Sign out</a></nav></div></header><main class="wrap" style="padding:36px 0"><div class="eyebrow">System control</div><h1 style="font:44px Georgia,serif">Administrator console</h1><p class="muted">Review contributor credentials, approve workspace access, and moderate submitted content before publication.</p><?php if($message):?><div class="panel"><?=$message?></div><?php endif;?><section class="panel" style="margin:20px 0"><h2>Account approval queue <span class="status"><?=count($pendingUsers)?> pending</span></h2><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Contributor details</th><th>Registered</th><th>Decision</th></tr></thead><tbody><?php foreach($pendingUsers as $u):?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['email'])?></td><td class="credential-cell"><?=nl2br(e($u['credential_notes']??'No details provided'))?></td><td><?=e($u['created_at'])?></td><td><form method="post" style="display:flex;gap:6px;flex-wrap:wrap"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><button class="btn" name="action" value="approve_user">Approve</button><button class="btn light" name="action" value="reject_user">Reject</button></form></td></tr><?php endforeach;?><?php if(!$pendingUsers):?><tr><td colspan="5">No accounts awaiting review.</td></tr><?php endif;?></tbody></table></section><section class="panel"><h2>Content moderation queue <span class="status"><?=count($pendingContent)?> pending</span></h2><table class="table"><thead><tr><th>Content</th><th>Creator</th><th>Category</th><th>Submitted</th><th>Decision</th></tr></thead><tbody><?php foreach($pendingContent as $c):?><tr><td><?=e($c['title'])?><br><small><?=e($c['content_type'])?></small></td><td><?=e($c['full_name'])?></td><td><?=e($c['category_name'])?></td><td><?=e($c['created_at'])?></td><td><form method="post" style="display:flex;gap:6px;flex-wrap:wrap"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="btn" name="action" value="publish">Publish</button><button class="btn light" name="action" value="reject_content">Reject</button></form></td></tr><?php endforeach;?><?php if(!$pendingContent):?><tr><td colspan="5">No content awaiting review.</td></tr><?php endif;?></tbody></table></section></main></body></html>
